base_model_response:
with {
  "select count(distinct s1.id) as result 
  from ( 
    select id from stream where total_view_count < followers group by id having count(*) = 1
  ) as t1,
  (
    select s2.* 
    from stream s2 join 
    (
      select id, max(total_view_count) as max_total_view_count, min(followers) as min_followers from stream where total_view_count < followers group by id having count(*) = 1
    ) as t2 on s2.id = t2.id and s2.total_view_count < s2.followers 
    where (total_view_count < followers or max_total_view_count = total_view_count) and (max_total_view_count = total_view_count or min_followers = followers)
  ) as t3
}

